Local Ltac2 e25kn_keep_near (t : Init.constr) : Init.unit :=
  let seed := FF5.ffn_vars (FSet.empty FSet.Tags.ident_tag) t in
  let e := LiaTuning.zf_mkenv () in
  let (ids, _) := List.fold_left (fun acc h =>
      let (ids, cache) := acc in
      let (id, body, ty) := h in
      match body with
      | Init.Some _ => acc
      | Init.None =>
          let (isp, cache) := LiaTuning.zf_is_prop cache ty in
          if isp then
            (if LiaTuning.zf_plain_arith e ty then
               (if FSet.is_empty (FSet.inter seed (FF5.ffn_vars (FSet.empty FSet.Tags.ident_tag) ty))
                then (id :: ids, cache) else (ids, cache))
             else (id :: ids, cache))
          else (ids, cache)
      end) ([], { LiaTuning.zc_c := FMap.empty FSet.Tags.constant_tag; LiaTuning.zc_i := FMap.empty FSet.Tags.inductive_tag })
      (Control.hyps ()) in
  match ids with
  | [] => ()
  | _ :: _ => match Control.case (fun () => Std.clear ids) with
              | Init.Val _ => ()
              | Init.Err _ => List.iter (fun id => match Control.case (fun () => Std.clear [id]) with Init.Val _ => () | Init.Err _ => () end) ids
              end
  end.
Ltac ff_keep_near t ::= let f := ltac2:(t |- e25kn_keep_near (Option.get (Ltac1.to_constr t))) in f t.

Definition A_PK_GET_PK_ALG : Z := 0xb0788.
Definition A_SMALLOC_1_GPA : Z := 0x5306c.
Definition A_AMEMSET_GPA : Z := 0x68258.
Definition A_ASN1_GET_ALG_GPA : Z := 0x9a9c0.
Definition A_OID_PK_ALG_GPA : Z := 0xa8520.
Definition A_OID_EC_GRP_GPA : Z := 0xa8b70.

Definition PK_GET_PK_ALG_STACK_A : Z := 4224.

Definition pk_get_pk_alg_postA (segs : list Segment) (R : art_layout) (HIA : artA segs R)
    (h : HST segs R HIA) (LB LF : list blk)
    (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (PP PA KA GA P END BUF lo slo : Z) (m0 : mem) : machine_state -> Prop := fun ms' =>
  exists (t0' t1' t2' a0 a1 a2 a3 a4 a5 a6 a7 t3' t4' t5' t6' : word) (m' : mem) (h' : HST segs R HIA)
    (r p' : Z) (ptag ppad plen ppw kv gv : word),
    ms' = MS (mkR ra sp gp tp t0' t1' t2' s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11
                t3' t4' t5' t6') F (ret_pc ra) fc None m' (seg_rom segs)
    /\ HM segs R HIA h' LB LF m'
    /\ hcs segs R HIA h' = hcs segs R HIA h
    /\ htop segs R HIA h' = htop segs R HIA h
    /\ hstkhi segs R HIA h' = hstkhi segs R HIA h
    /\ hflag segs R HIA h' = hflag segs R HIA h
    /\ havol segs R HIA h' = havol segs R HIA h
    /\ hfr segs R HIA h' = hfr segs R HIA h
    /\ (forall mo : Model, HK segs R HIA h' mo <-> HK segs R HIA h mo)
    /\ presA segs R LB LF (bv_unsigned sp) (arl_stklo R) (hstkhi segs R HIA h)
         [(PP, PP + 8); (PA, PA + 24); (KA, KA + 4); (GA, GA + 4)] m0 m'
    /\ mem_inv segs m'
    /\ stk segs m' lo (bv_unsigned sp)
    /\ sshad segs (arl_AL R) m' slo (bv_unsigned sp)
    /\ a0 = Z_to_bv 64 r
    /\ - 2^31 < r <= 0
    /\ rw_cells segs m' PP [C8 (Z_to_bv 64 p')]
    /\ rw_cells segs m' PA [C4 ptag; C4 ppad; C8 plen; C8 ppw]
    /\ rw_cells segs m' KA [C4 kv]
    /\ rw_cells segs m' GA [C4 gv]
    /\ P <= p' <= END
    /\ (r = 0 -> (bv_unsigned ppw = 0 /\ bv_unsigned plen = 0 /\ ptag = Z_to_bv 64 0)
                \/ (BUF <= bv_unsigned ppw /\ P <= bv_unsigned ppw /\ bv_unsigned ppw + bv_unsigned plen <= END)).

Definition pk_get_pk_alg_stmtA (segs : list Segment) (R : art_layout) (HIA : artA segs R) (ENTRY : Z) : Prop :=
  forall (h : HST segs R HIA) (LB LF : list blk)
    (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (m : mem) (PP PA KA GA P END BUF lo slo : Z) (bs jpa : list byte)
    (kv0 gv0 : word),
  HM segs R HIA h LB LF m -> (length LF < 512)%nat ->
  rw_cells segs m PP [C8 (Z_to_bv 64 P)] ->
  rw_cells segs m PA [CB 24 jpa] ->
  rw_cells segs m KA [C4 kv0] ->
  rw_cells segs m GA [C4 gv0] ->
  bytes_at segs m BUF bs ->
  BUF <= P -> P <= END -> END <= BUF + Z.of_nat (length bs) -> BUF + Z.of_nat (length bs) < 2^63 ->
  0 < Z.of_nat (length bs) ->
  BUF + Z.of_nat (length bs) + 8 <= 2^47 ->
  PP + 8 <= PA \/ PA + 24 <= PP ->
  PP + 8 <= KA \/ KA + 4 <= PP ->
  PP + 8 <= GA \/ GA + 4 <= PP ->
  PA + 24 <= KA \/ KA + 4 <= PA ->
  PA + 24 <= GA \/ GA + 4 <= PA ->
  KA + 4 <= GA \/ GA + 4 <= KA ->
  Z.of_nat (length bs) = 0 \/ PP + 8 <= BUF \/ BUF + Z.of_nat (length bs) <= PP ->
  Z.of_nat (length bs) = 0 \/ PA + 24 <= BUF \/ BUF + Z.of_nat (length bs) <= PA ->
  Z.of_nat (length bs) = 0 \/ KA + 4 <= BUF \/ BUF + Z.of_nat (length bs) <= KA ->
  Z.of_nat (length bs) = 0 \/ GA + 4 <= BUF \/ BUF + Z.of_nat (length bs) <= GA ->
  PP mod 8 = 0 -> PA mod 8 = 0 -> KA mod 4 = 0 -> GA mod 4 = 0 ->
  0 < PP /\ PP + 8 <= 2^64 -> 0 < PA /\ PA + 24 <= 2^64 ->
  0 < KA /\ KA + 4 <= 2^64 -> 0 < GA /\ GA + 4 <= 2^64 -> 0 < BUF ->
  stk segs m lo (bv_unsigned sp) -> sshad segs (arl_AL R) m slo (bv_unsigned sp) ->
  lo <= bv_unsigned sp - PK_GET_PK_ALG_STACK_A ->
  lo <= bv_unsigned sp - 320 - arl_need_amem R ->
  lo <= bv_unsigned sp - 144 - arl_need_smalloc R ->
  lo <= bv_unsigned sp - 176 - arl_need_bcmp R ->
  0 <= arl_need_amem R -> 0 <= arl_need_smalloc R -> 0 <= arl_need_bcmp R ->
  arl_stklo R <= slo -> slo <= lo ->
  bv_unsigned sp mod 16 = 0 -> bv_unsigned sp <= htop segs R HIA h -> bv_unsigned sp <= 2^47 ->
  PP + 8 <= lo \/ bv_unsigned sp <= PP ->
  PA + 24 <= lo \/ bv_unsigned sp <= PA ->
  KA + 4 <= lo \/ bv_unsigned sp <= KA ->
  GA + 4 <= lo \/ bv_unsigned sp <= GA ->
