Lemma gpa_sub_bytes : forall (segs : list Segment) (mq : mem) (A : Z) (xs : list byte) (p ln : Z),
  bytes_at segs mq A xs -> A <= p -> 0 <= ln -> p + ln <= A + Z.of_nat (length xs) ->
  bytes_at segs mq p (firstn (Z.to_nat ln) (skipn (Z.to_nat (p - A)) xs))
  /\ Z.of_nat (length (firstn (Z.to_nat ln) (skipn (Z.to_nat (p - A)) xs))) = ln.
Proof.
  intros segs mq A xs p ln HB H1 H2 H3.
  rewrite <- (firstn_skipn (Z.to_nat (p - A)) xs) in HB.
  apply bytes_at_app in HB. destruct HB as [_ HB].
  rewrite length_firstn in HB.
  replace (A + Z.of_nat (Nat.min (Z.to_nat (p - A)) (length xs))) with p in HB by lia.
  assert (LY : Z.of_nat (length (skipn (Z.to_nat (p - A)) xs)) = Z.of_nat (length xs) - (p - A))
    by (rewrite length_skipn; lia).
  rewrite <- (firstn_skipn (Z.to_nat ln) (skipn (Z.to_nat (p - A)) xs)) in HB.
  apply bytes_at_app in HB. destruct HB as [HB _].
  split; [exact HB|]. rewrite length_firstn. lia.
Qed.
