Lemma gpa_cb4_c4 : forall segs m A pre bs post,
  rw_cells segs m A (pre ++ CB 4 bs :: post) -> rw_cells segs m A (pre ++ C4 (le_bytes_to_word bs) :: post).
Proof.
  intros segs m A pre bs post [[Hwf Hb] Hw].
  apply cells_wf_app in Hwf. destruct Hwf as [H1 [H2 H3]]. cbn in H2.
  split; [split|].
  - apply cells_wf_app. split; [exact H1|]. split; [exact I| exact H3].
  - rewrite !cells_bytes_app in *. cbn [cells_bytes cbytes] in *. rewrite gpa_le4 by exact H2. exact Hb.
  - rewrite !cells_size_app in *. cbn [cells_size csize] in *. exact Hw.
Qed.

Lemma gpa_cb24_cells : forall (segs : list Segment) (mq : mem) (A : Z) (j : list byte),
  rw_cells segs mq A [CB 24 j] ->
  exists a b c d, rw_cells segs mq A [C4 a; C4 b; C8 c; C8 d].
Proof.
  intros segs mq A j H.
  apply (rw_cells_split_CB segs mq A [] 24 j [] [4; 4; 8; 8]%nat) in H; [| reflexivity].
  cbn [mk_CB_cells app] in H.
  apply (gpa_cb4_c4 segs mq A []) in H. cbn [app] in H.
  match type of H with rw_cells _ _ _ (?c1 :: _) => apply (gpa_cb4_c4 segs mq A [c1]) in H end. cbn [app] in H.
  match type of H with rw_cells _ _ _ (?c1 :: ?c2 :: _) => apply (rw_cells_CB8_C8 segs mq A [c1; c2]) in H end. cbn [app] in H.
  match type of H with rw_cells _ _ _ (?c1 :: ?c2 :: ?c3 :: _) => apply (rw_cells_CB8_C8 segs mq A [c1; c2; c3]) in H end. cbn [app] in H.
  eexists _, _, _, _. exact H.
Qed.

