  Tactic Notation "callxA_sp_cs" constr(e) constr(E) tactic3(apptac) :=
    lazymatch goal with
    | |- evtA ?segs _ _ _ (MS _ _ _ _ _ ?m _) =>
        eapply evtA_cut_mono;
        [ apptac
        | let x := fresh "x" in let Hx := fresh "Hx" in intros x Hx;
          first [ rewrite <- E; exact Hx | rewrite E in Hx; exact Hx | rewrite <- E in Hx; exact Hx ]
        | lazymatch goal with |- forall x, ?P x -> _ => let hd := head_of P in try unfold hd end;
          rewrite ?(unsigned_lit e) by qlia; post_callA segs m ]
    end.

  Ltac gpa_oid OPX FBv h1v sp1v EXTv ECSv ETOPv :=
    lxr_leaf;
    lazymatch goal with
    | HA : rw_cells _ ?mx (FBv + 32) [C4 (Z_to_bv 64 ?tgv); C4 (Z_to_bv 64 ?pdv); C8 (Z_to_bv 64 ?lnv); C8 (Z_to_bv 64 ?pwv)],
      HB : bytes_at _ ?mx P ?bsq, OB : aobj _ _ _ ?mx P _, HSH : rw_cells _ ?mx (Z.shiftr FBv 3 + al_sb AL) _,
      HE : rw_cells _ ?mx EXTv [C4 ?v0x] |- _ =>
      let HOB := fresh "HOB" in let OLEN := fresh "OLEN" in let OOID := fresh "OOID" in let OOB := fresh "OOB" in
      destruct (gpa_sub_bytes asegs mx P bsq pwv lnv HB ltac:(clear_disj; lia) ltac:(clear_disj; lia) ltac:(clear_disj; lia)) as [HOB OLEN];
      assert (OOID : aobj asegs AL CS mx (FBv + 32) 24)
        by (clear_disj; let OO := fresh "OO" in frame_aobj HSH (FBv + 32) 3%nat as OO; exact OO);
      assert (OOB : aobj asegs AL CS mx pwv lnv) by (eapply aobj_sub; [exact OB | clear_disj; lia | clear_disj; lia]);
      callxA_sp_cs sp1v ECSv
        (eapply OPX with (h := h1v) (LB := LB) (LF := (FBv, 128) :: LF) (OID := FBv + 32) (EXT := EXTv) (P := pwv) (LEN := lnv) (lo := lo)
                         (tg := Z_to_bv 64 tgv) (pd := Z_to_bv 64 pdv) (v0 := v0x) (xs := firstn (Z.to_nat lnv) (skipn (Z.to_nat (pwv - P)) bsq));
         rewrite ?(unsigned_lit sp1v) by (clear_disj; lia); rewrite ?ETOPv, ?ECSv;
         first [ exact HA | exact HOB | exact OLEN | exact OOID | exact OOB | exact LOS | eassumption | reflexivity
               | lazymatch goal with |- client_wrange _ _ _ _ _ _ => solve_client_wrange end
               | lazymatch goal with
                 | |- _ \/ _ => first [ solve [clear_mods; clear_disj; lia] | pqlia ]
                 | |- _ => first [ solve [clear_disj; lia] | qlia | pqlia ] end ])
    end.

  Ltac gpa_hr0 :=
    lazymatch goal with
    | |- 0 = 0 -> (bv_unsigned (Z_to_bv 64 ?pw) = 0 /\ bv_unsigned (Z_to_bv 64 ?pl) = 0 /\ Z_to_bv 64 ?pt = Z_to_bv 64 0) \/ _ =>
        intros _;
        rewrite ?(unsigned_lit pw) by (clear_disj; lia); rewrite ?(unsigned_lit pl) by (clear_disj; lia);
        let E0 := fresh "E0" in
        destruct (Z.eq_dec pw 0) as [E0|E0];
        [ left; split; [exact E0|]; split;
          [ match goal with H : pl = 0 \/ _ \/ _ |- _ =>
              destruct H as [H|[H|H]]; [exact H| exfalso; clear_disj; lia| exfalso; clear_disj; lia] end
          | match goal with H : pt = 0 \/ _ \/ _ |- _ =>
              destruct H as [H|[H|H]]; [rewrite H; reflexivity| exfalso; clear_disj; lia| exfalso; clear_disj; lia] end ]
        | right;
          match goal with H : pw = 0 \/ _ \/ 0 + P <= pw |- _ =>
            destruct H as [H|[H|H]]; [exfalso; exact (E0 H)| exfalso; clear_disj; lia|] end;
          match goal with H : pw = 0 \/ _ \/ 0 + (pl + pw) <= _ |- _ =>
            destruct H as [H|[H|H]]; [exfalso; exact (E0 H)| exfalso; clear_disj; lia|] end;
          repeat split; clear_disj; lia ]
    end.

  Ltac gpa_epi :=
    lxr_leaf;
    first [ (eapply epi_walk; first [ lx_is_mem_goal; eassumption | lazymatch goal with |- @eq (bv _) _ _ => reflexivity end | gpa_hr0 | idtac ])
          | (eapply evtA_eq; [ apply lx_MS_regs | eapply epi_walk; first [ lx_is_mem_goal; eassumption | lazymatch goal with |- @eq (bv _) _ _ => reflexivity end | gpa_hr0 | idtac ] ]) ];
    try lx_regs_eq; lx_app.


