  Lemma body_walk : forall (FB spv s2v sp1 sh2 : Z) (LF' : list blk) (h1 : HST asegs R HIA) (m0 mm : mem)
      (x5 x6 x7 x10 x11 x12 x13 x14 x15 x16 x17 x28 x29 x30 x31 s8v s9v : word)
      (junk1 junk2 j3 jrz : list byte),
    HM asegs R HIA h1 LB LF' mm -> hcs asegs R HIA h1 = CS -> htop asegs R HIA h1 = htop asegs R HIA h ->
    hstkhi asegs R HIA h1 = hstkhi asegs R HIA h -> (forall mo, HK asegs R HIA h1 mo <-> HK asegs R HIA h mo) ->
    hflag asegs R HIA h1 = hflag asegs R HIA h -> havol asegs R HIA h1 = havol asegs R HIA h -> hfr asegs R HIA h1 = hfr asegs R HIA h ->
    bv_unsigned sp - 144 <= sp1 <= bv_unsigned sp - 128 -> sp1 mod 32 = 0 ->
    rw_cells asegs mm FB [CB 24 junk1] -> rw_cells asegs mm (FB + 24) [CB 8 j3] ->
    rw_cells asegs mm (FB + 32) [CB 24 junk2] -> rw_cells asegs mm (FB + 56) [CB 40 jrz] ->
    rw_cells asegs mm (Z.shiftr FB 3 + al_sb AL) (zcells 16) ->
    crange CS FB 128 -> FB mod 32 = 0 -> 0 < FB -> FB + 96 <= sp1 ->
    client_wrange L (LB ++ fdata LF') (arl_stklo R) (htop asegs R HIA h) FB 24 ->
    client_wrange L (LB ++ fdata LF') (arl_stklo R) (htop asegs R HIA h) (FB + 32) 64 ->
    (forall x, FB <= x < FB + 128 -> (arl_stklo R <= x < htop asegs R HIA h) \/ in_block LF' x) ->
    (forall b, In b (LB ++ fdata LF) -> In b (LB ++ fdata LF')) ->
    (FB + 128 <= PP \/ PP + 8 <= FB) -> (FB + 128 <= PA \/ PA + 24 <= FB) ->
    (FB + 128 <= KA \/ KA + 4 <= FB) -> (FB + 128 <= GA \/ GA + 4 <= FB) ->
    (Z.of_nat (length bs) = 0 \/ FB + 128 <= BUF \/ BUF + Z.of_nat (length bs) <= FB) ->
    stk asegs mm lo spv -> lo <= spv - 96 - arl_need_amem R -> spv mod 16 = 0 -> spv <= sp1 -> (FB + 128 <= arl_stklo R \/ spv = FB) ->
    sp1 <= sh2 <= sp1 + 32 ->
    stk asegs mm sp1 (bv_unsigned sp + -104) -> rw_cells asegs mm (sp1 + 16) [C8 (Z_to_bv 64 FB)] ->
    rw_cells asegs mm (bv_unsigned sp + -104) [C8 s11; C8 s10; C8 s9; C8 s8; C8 s7; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra] ->
    rw_cells asegs mm PP [C8 (Z_to_bv 64 P)] -> rw_cells asegs mm PA [CB 24 jpa] ->
    rw_cells asegs mm KA [C4 kv0] -> rw_cells asegs mm GA [C4 gv0] -> bytes_at asegs mm BUF bs ->
    aobj asegs AL CS mm PP 8 -> aobj asegs AL CS mm PA 24 -> aobj asegs AL CS mm KA 4 -> aobj asegs AL CS mm GA 4 ->
    aobj asegs AL CS mm BUF (Z.of_nat (length bs)) ->
    abase asegs AL mm -> mem_inv asegs mm ->
    presW asegs R HIA h LB LF (bv_unsigned sp) (arl_stklo R) W m0 mm ->
    wlow R LB LF -> wcover R LB LF (bv_unsigned sp) W FB 96 ->
    shadow_free R LB LF (arl_stklo R) (hstkhi asegs R HIA h) FB 128 ->
    sshad asegs AL mm slo spv -> sshad asegs AL mm sh2 (bv_unsigned sp) ->
    PATH FB spv s2v sp1 sh2 LF' ->
    evtA asegs AL CS (POSTA m0)
      (MS (mkR (Z_to_bv 64 0xb0808) (Z_to_bv 64 spv) gp tp x5 x6 x7 sp (Z_to_bv 64 sp1)
              x10 x11 x12 x13 x14 x15 x16 x17
              (Z_to_bv 64 s2v) (Z_to_bv 64 KA) (Z_to_bv 64 PA) (Z_to_bv 64 GA) (Z_to_bv 64 END) (Z_to_bv 64 PP)
              s8v s9v (Z_to_bv 64 FB) (Z_to_bv 64 (al_sb AL))
              x28 x29 x30 x31)
          F (Z_to_bv 64 0xb0844) fc None mm (seg_rom asegs)).
  Proof.
  intros until jrz.
  intros HH ECS ETOP ESTK HKI EFLAG EVOL EFR SP1 SP1M FH G1 FD RZ FSH CFB FBAL FB0 FBS1 FWH FWD FWS SUBLF AP1 AP2 AP3 AP5 AP4
  ST1 SLO16 SPVA SPV1 SEPF SH2 STK2 SLOT SPILL HPP HPA HKA HGA HBUF OPP OPA OKA OGA OBUF AB MI PRES WL WCF SFF SS1 SS2 HPATH.
  destruct HPATH as (Es2 & ELF & Espv & Esh2 & FRSH & F64). subst s2v LF' spv sh2.
  rt_facts.
  pose proof (hm_top asegs R HIA h1 LB _ _ HH) as HTOP.
  rewrite ETOP, ESTK in HTOP.
  assert (SCS : crange CS lo (bv_unsigned sp - lo)) by (eapply crange_sub; [exact SCS0| qlia| qlia]).
  cbn [zcells] in FSH.
  assert (OSL : aobj asegs AL CS mm (sp1 - 72) 8) by
    (apply (gpa_aobj_of_sshad0 AL CS mm slo sp1 (sp1 - 72) 0 CSOK SS1);
     [ clear - SLO16 SLOL RTA0; lia | clear; lia | clear - SPVA; lia | clear - SLO16 SLOL SLOS RTA0 ALO ACP; lia
     | eapply crange_sub; [exact SCS | clear - SLO16 RTA0; lia | clear - SP1; lia] ]).
  destruct (gpa_sub_bytes asegs mm BUF bs P (BUF + Z.of_nat (length bs) - P) HBUF B1 ltac:(clear - B2 B3; lia) ltac:(clear; lia)) as [HBP LBP].
  set (bsp := firstn (Z.to_nat (BUF + Z.of_nat (length bs) - P)) (skipn (Z.to_nat (P - BUF)) bs)) in HBP, LBP.
  assert (OBP : aobj asegs AL CS mm P (Z.of_nat (length bsp))) by (eapply aobj_sub; [exact OBUF | clear - B1; lia | rewrite LBP; clear; lia]).
  clear HBUF OBUF. clearbody bsp.
  destruct (gpa_cb24_cells asegs mm (FB + 32) junk2 FD) as (o1 & o2 & o3 & o4 & FD4). clear FD.
  assert (BP1 : PP + 8 <= P \/ P + Z.of_nat (length bsp) <= PP) by (clear - D4 B1 LBP BL0 B2 B3; lia).
  assert (BP2 : PA + 24 <= P \/ P + Z.of_nat (length bsp) <= PA) by (clear - D5 B1 LBP BL0 B2 B3; lia).
  assert (BP3 : KA + 4 <= P \/ P + Z.of_nat (length bsp) <= KA) by (clear - D9 B1 LBP BL0 B2 B3; lia).
  assert (BP5 : GA + 4 <= P \/ P + Z.of_nat (length bsp) <= GA) by (clear - D10 B1 LBP BL0 B2 B3; lia).
  assert (BP4 : FB + 128 <= P \/ P + Z.of_nat (length bsp) <= FB) by (clear - AP4 B1 LBP BL0 B2 B3; lia).
  assert (BPS : P + Z.of_nat (length bsp) <= lo \/ bv_unsigned sp <= P) by (clear - DS4 B1 LBP BL0 B2 B3; lia).
  assert (BPL : P + Z.of_nat (length bsp) < 2^63) by (clear - B4 LBP; lia).
  assert (BPE : END <= P + Z.of_nat (length bsp)) by (clear - B3 LBP; lia).
  assert (BP0 : 0 < P) by (clear - BUF0 B1; lia).
  assert (BPH : P + Z.of_nat (length bsp) + 8 <= 2^47) by (clear - B47 LBP; lia).
  lx_pre. lxr_abase. lxr_pose.
  lxa_auto [SUM_amemset0A 24 [lxz4; lxz4; lxz8; lxz8] 6; SUM_getalgA 5 4 6] [FB + 32; PP; PA].
  lx_pre. lx_run_tac (PLANS [0xb09b8; 0xb08e8; 0xa8520] [] 300%N [SUM_amemset0A 24 [lxz4; lxz4; lxz8; lxz8] 6; SUM_getalgA 5 4 6]). lx_tree. all: lxa_unglob.
