  Lemma main_walk : forall (x5 x6 x7 a5 a6 a7 x28 x29 x30 x31 : word),
    HM asegs R HIA h LB LF m ->
    rw_cells asegs m PP [C8 (Z_to_bv 64 P)] -> rw_cells asegs m PA [CB 24 jpa] ->
    rw_cells asegs m KA [C4 kv0] -> rw_cells asegs m GA [C4 gv0] -> bytes_at asegs m BUF bs ->
    stk asegs m lo (bv_unsigned sp) -> sshad asegs AL m slo (bv_unsigned sp) -> mem_inv asegs m ->
    aobj asegs AL CS m PP 8 -> aobj asegs AL CS m PA 24 -> aobj asegs AL CS m KA 4 -> aobj asegs AL CS m GA 4 ->
    aobj asegs AL CS m BUF (Z.of_nat (length bs)) ->
    evtA asegs AL CS (POSTA m)
      (MS (mkR ra sp gp tp x5 x6 x7 s0 s1 (Z_to_bv 64 PP) (Z_to_bv 64 END) (Z_to_bv 64 KA) (Z_to_bv 64 PA) (Z_to_bv 64 GA)
              a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 x28 x29 x30 x31)
          F (Z_to_bv 64 A_PK_GET_PK_ALG) fc None m (seg_rom asegs)).
  Proof.
    intros until x31. intros HH HPP HPA HKA HGA HBUF ST SS MI OPP OPA OKA OGA OBUF.
    unfold A_PK_GET_PK_ALG. unfold A_UAR_GOT_GPA in UARG. unfold A_SMALLOC_1_GPA in SM1.
    rt_facts.
    pose proof (hm_top asegs R HIA h LB LF _ HH) as HTOP.
    assert (SCS : crange CS lo (bv_unsigned sp - lo)) by (eapply crange_sub; [exact SCS0| qlia| qlia]).
    pose proof (hm_wlow asegs R HIA h LB LF m HH) as WL.
    pose proof (presW_init asegs R HIA h LB LF m (bv_unsigned sp) (arl_stklo R) W HH ltac:(clear - LOS SLO; lia)) as PRES.
    ddestruct IMG' as (EGOT & ELO & EHI & EGSB).
    zstep. carve_frame 128%nat ST.
    do 14 zstep.
    zstep. zstep.
    align32 (bv_unsigned sp + -128) sp1.
    assert (SP1 : bv_unsigned sp - 144 <= sp1 <= bv_unsigned sp - 128) by (clear - Hsp1 SPA SPR; subst sp1; lia).
    assert (SP1M : sp1 mod 32 = 0) by (clear - Hsp1 SPR; subst sp1; lia).
    clear Hsp1.
    do 7 zstep.
    lazymatch goal with |- _ (MS _ _ _ _ _ ?mc _) =>
      lazymatch goal with HHc : HM _ _ _ h LB LF mc |- _ =>
        pose proof (hm_abase asegs R HIA h LB LF mc HHc) as AB;
        pose proof (abase_got _ _ _ AB) as GOT; pose proof (abase_gsb _ _ _ AB) as GSB;
        destruct (hm_auar asegs R HIA h LB LF mc HHc) as [UGOT UFLAG];
        pose proof (hm_flag_img asegs R HIA h LB LF mc HHc) as FLIMG
      end end.
    rewrite EGOT in GOT. rewrite UARG in UGOT.
    do 4 zstep.
    do 3 zstep.
    clear GOT GSB UGOT UFLAG AB FLIMG.
    zstep.
    lazymatch goal with |- _ (MS _ _ _ _ _ ?mc _) => rename mc into m1 end.
    destruct (stk_split asegs m1 lo sp1 (bv_unsigned sp + -128) ST ltac:(clear - SP1 SLO; lia)) as [ST1 ST2]. clear ST.
    replace (Z_to_bv 64 0x5306c) with (Z_to_bv 64 (arl_smalloc R 1)) by (rewrite SM1; reflexivity).
    lazymatch goal with HHc : HM _ _ _ h LB LF m1 |- _ =>
    callrt sp1 (eapply (art_smalloc asegs R HIA 1) with (lo := lo) (sz := 96);
                [ exact HHc | exact LFB | clear; lia | clear; lia | rewrite (unsigned_lit sp1) by (clear - SP1 SPR SLO LOS ALO ACV; lia); exact ST1
                | exact LOS | rewrite (unsigned_lit sp1) by (clear - SP1 SPR SLO LOS ALO ACV; lia); clear - SLO3 SP1; lia
                | rewrite (unsigned_lit sp1) by (clear - SP1 SPR SLO LOS ALO ACV; lia); clear - SP1 TOP; lia
                | assumption | exact TPV | reflexivity ])
    end.
    clear ST1.
    lazymatch goal with H : presA _ _ _ _ _ _ _ _ m1 ?m2 |- _ => rename H into HP1; rename m2 into m2' end.
    clear HH.
    presA_transport HP1. clear HP1.
    lazymatch goal with H : exists h' : HST _ _ _, _ |- _ =>
      destruct H as (h1 & Ehcs & Ehtop & Estk & Eflag & Evol & Efr & HKI & SMC) end.
    ddestruct SMC as (FB & junkf & Ea0 & F64 & FRSH & HH1 & FRM & FSH). lazymatch type of Ea0 with ?x = _ => subst x end.
      replace (Z.to_nat (8 * 2 ^ 1)) with 16%nat in FSH by reflexivity.
      replace (Z.to_nat (64 * 2 ^ 1)) with 128%nat in FRM by reflexivity.
      replace (64 * 2 ^ 1) with 128 in FRSH, HH1 by reflexivity.
      cbn [zcells] in FSH.
      zstep. zstep.
      zstep. if_cases Kb; zify_cond Kb; [| exfalso; ddestruct FRSH as (F0 & F1 & _); clear - Kb F0 F1 ALO ACV LOS SLO SPR; lia ].
      lazymatch goal with |- _ (MS _ _ _ _ _ ?mc _) => rename mc into m3 end.
      apply (rw_cells_split_CB asegs m3 FB [] 128 junkf [] [24; 8; 24; 40; 32]%nat) in FRM; [| reflexivity].
      cbn [mk_CB_cells app] in FRM.
      chunk_split FRM 1%nat FH FRM1. chunk_split FRM1 1%nat G1 FRM2. chunk_split FRM2 1%nat FD FRM3. chunk_split FRM3 1%nat RZB G2. clear G2.
      replace (FB + 24 + 8) with (FB + 32) in FD, RZB by (clear; lia). replace (FB + 32 + 24) with (FB + 56) in RZB by (clear; lia).
      lazymatch goal with SSx : sshad _ _ m3 slo (bv_unsigned sp) |- _ =>
        destruct (sshad_split asegs AL m3 slo sp1 (bv_unsigned sp) SSx ltac:(clear - SP1 SLO SLOL; lia) ltac:(clear - SP1M; lia)) as [SS1 SS2]; clear SSx end.
      lazymatch goal with FRx : rw_cells _ m3 (bv_unsigned sp + -128) _ |- _ => chunk_split FRx 2%nat FRa SPILL end.
      replace (bv_unsigned sp + -128 + 24) with (bv_unsigned sp + -104) in SPILL by (clear; lia).
      lazymatch goal with ST2x : stk _ m3 sp1 (bv_unsigned sp + -128) |- _ => release_frame FRa ST2x (bv_unsigned sp + -104); rename ST2x into STK2 end.
      destruct (stk_slot asegs m3 sp1 (bv_unsigned sp + -104) (sp1 + 16) 8 STK2 ltac:(clear; lia) ltac:(clear - SP1; lia)) as [jsp0 SLOT0].
      cb8_to_c8 SLOT0 (@nil cell). rename SLOT0 into SLOT.
      assert (INF : In (FB, 128) ((FB, 128) :: LF)) by (left; reflexivity).
      pose proof (hcs_fake asegs R HIA h1 LB _ m3 FB 128 HH1 INF) as CFB. rewrite Ehcs in CFB.
      assert (INH : In (FB, 24) (LB ++ fdata ((FB, 128) :: LF))) by (apply in_app_iff; right; left; reflexivity).
      assert (IND : In (FB + 32, 88) (LB ++ fdata ((FB, 128) :: LF))) by (apply in_app_iff; right; right; left; reflexivity).
      pose proof (fresh_apart_client _ LB LF lo PP 8 FB 128 FRSH CR1 ltac:(clear; lia) ltac:(clear; lia) ltac:(clear - ALO LOS; lia)) as AP1.
      pose proof (fresh_apart_client _ LB LF lo PA 24 FB 128 FRSH CR2 ltac:(clear; lia) ltac:(clear; lia) ltac:(clear - ALO LOS; lia)) as AP2.
      pose proof (fresh_apart_client _ LB LF lo KA 4 FB 128 FRSH CR3 ltac:(clear; lia) ltac:(clear; lia) ltac:(clear - ALO LOS; lia)) as AP3.
      pose proof (fresh_apart_client _ LB LF lo GA 4 FB 128 FRSH CR5 ltac:(clear; lia) ltac:(clear; lia) ltac:(clear - ALO LOS; lia)) as AP5.
      pose proof (fresh_apart_client0 _ LB LF lo BUF (Z.of_nat (length bs)) FB 128 FRSH CR4 ltac:(clear; lia) ltac:(clear; lia) ltac:(clear - ALO LOS; lia)) as AP4.
      pose proof FRSH as FRSH'. unfold fresh_apart in FRSH'.
      zstep.
      lazymatch goal with |- _ (MS _ _ _ _ _ ?mc _) => rename mc into m4 end.
      pose proof (hm_abase asegs R HIA h1 LB _ m4 ltac:(eassumption)) as AB3.
      eapply body_walk with (FB := FB) (spv := sp1) (s2v := FB) (sp1 := sp1) (sh2 := sp1) (LF' := (FB, 128) :: LF) (h1 := h1) (m0 := m).
      all: bw_side.
  Qed.
  Local Ltac2 Set LiaOrc.tbl := fun () => "".

End Walk.

Lemma A_pk_get_pk_alg_spec : forall (R : art_layout) (HIA : artA asegs R),
  asan_img_ok (arl_AL R) ->
  arl_uar_got R = A_UAR_GOT_GPA -> arl_smalloc R 1 = A_SMALLOC_1_GPA -> arl_amemset R = A_AMEMSET_GPA ->
  arl_memset_i R = A_WRAP_MEMSET -> (forall m, arl_rtc R m -> asan_rtc m) -> 0 <= arl_need_amem R ->
  oid_rt_hyps R HIA ->
  pk_get_pk_alg_stmtA asegs R HIA A_PK_GET_PK_ALG.
Proof.
  intros R HIA IMG UARG SM1 AMS MSI RTC NEED0 ORT.
  pose proof (A_asn1_get_alg_spec R HIA IMG MSI RTC NEED0) as GAS.
  pose proof (A_oid_get_pk_alg_spec R HIA ORT) as OPKS.
  pose proof (A_oid_get_ec_grp_algid_spec R HIA ORT) as OECS.
  unfold pk_get_pk_alg_stmtA. intros. subst.
  eapply main_walk; eauto.
Qed.
